using System;
using System.Reflection;
using Kamilunavo.RepairEmpire.Core;
using Kamilunavo.RepairEmpire.Monetization;
namespace Kamilunavo.RepairEmpire.Validation {
 public static class RepairInterstitialChecks {
  public static int Run(){int n=0;Action<bool,string> check=(ok,name)=>{n++;if(!ok)throw new Exception("REPAIR_INTERSTITIAL_FAIL "+name);};
   var assembly=typeof(RepairProfile).Assembly;var policy=assembly.GetType("Kamilunavo.RepairEmpire.Monetization.InterstitialPolicy");var boundary=assembly.GetType("Kamilunavo.RepairEmpire.Monetization.InterstitialBoundary");
   check(policy!=null&&boundary!=null,"paid-result interstitial policy exists");
   Func<object> fresh=()=>Activator.CreateInstance(policy,new object[]{100d});
   Func<object> ready=()=>{var b=Activator.CreateInstance(boundary);foreach(var f in new[]{"Parked","ResultModal","Focused","Consent","Ready"})boundary.GetField(f).SetValue(b,true);return b;};
   Func<object,long,string,bool> paid=(gate,t,id)=>(bool)policy.GetMethod("RecordPaid").Invoke(gate,new object[]{t,id});
   Func<object,long,double,object,bool> result=(gate,t,time,b)=>(bool)policy.GetMethod("TryAtResult").Invoke(gate,new object[]{t,time,b});
   var g=fresh();check(!paid(g,0,"faucet")&&!paid(g,1,""),"invalid payments do not count");check(paid(g,1,"faucet")&&!paid(g,1,"faucet")&&!paid(g,2,"faucet"),"paid contract counted once despite callbacks/tickets");check(!result(g,1,1000,ready()),"one paid order insufficient");check(paid(g,2,"toilet")&&!result(g,2,1000,ready()),"two paid orders insufficient");check(paid(g,3,"sink")&&!result(g,3,279.999,ready()),"180seconds from session start required");check(!result(g,3,280,ready()),"skipped boundary cannot show later when time becomes eligible");check(paid(g,4,"switch")&&result(g,4,280,ready()),"only new paid result can show after time threshold");check(!result(g,4,500,ready()),"result reopening cannot repeat opportunity");policy.GetMethod("MarkOpened").Invoke(g,new object[]{280d});
   check(paid(g,5,"pump")&&!result(g,5,1000,ready()),"new ad requires three further paid orders");paid(g,6,"boiler");paid(g,7,"vent");check(!result(g,7,459.999,ready()),"180seconds since actual ad opened");paid(g,8,"drain");check(result(g,8,460,ready()),"exact cooldown boundary");
   foreach(var field in new[]{"RemoveAds","Tutorial","RepairOpen","ProviderBusy"}){var gate=fresh();paid(gate,1,"a");paid(gate,2,"b");paid(gate,3,"c");var b=ready();boundary.GetField(field).SetValue(b,true);check(!result(gate,3,1000,b),field+" blocks interstitial");boundary.GetField(field).SetValue(b,false);check(!result(gate,3,1001,b),field+" skipped result never queues");}
   foreach(var field in new[]{"Parked","ResultModal","Focused","Consent","Ready"}){var gate=fresh();paid(gate,1,"a");paid(gate,2,"b");paid(gate,3,"c");var b=ready();boundary.GetField(field).SetValue(b,false);check(!result(gate,3,1000,b),field+" required");boundary.GetField(field).SetValue(b,true);check(!result(gate,3,1001,b),field+" recovery cannot surprise later");}
   foreach(double time in new[]{double.NaN,double.PositiveInfinity,99d}){var gate=fresh();paid(gate,1,"a");paid(gate,2,"b");paid(gate,3,"c");check(!result(gate,3,time,ready()),"invalid/reversed clock rejected");}
   var remove=typeof(CommerceRules).GetField("RemoveAds");check(remove!=null,"Remove Ads distinct store product");string id=(string)remove.GetValue(null);var p=new RepairProfile();int cash=p.Cash;check(CommerceRules.KnownProduct(id)&&CommerceRules.FulfillPending(p,id,"remove1",x=>{}),"verified Remove Ads grant");check(p.Cash==cash&&p.Commerce.Entitlements==4&&!p.Styles[4],"Remove Ads only grants own entitlement");check(CommerceRules.FulfillPending(p,id,"remove1",x=>{})&&p.Cash==cash&&p.Commerce.FulfilledTransactions.Count==1,"duplicate receipt idempotent");var restored=new RepairProfile();check(CommerceRules.RestoreEntitlement(restored,id)&&restored.Commerce.Entitlements==4&&restored.Cash==cash,"restore suppresses ads without cash");CommerceRules.ReconcileEntitlements(restored,new string[0]);check(restored.Commerce.Entitlements==0,"revocation removes suppression");var legacy=new RepairProfile();legacy.Commerce.Entitlements=3;legacy.Normalize();check(legacy.Commerce.Entitlements==3,"existing premium save migration remains unchanged");bool failed=false;var rollback=new RepairProfile();try{CommerceRules.FulfillPending(rollback,id,"diskfail",x=>{throw new Exception();});}catch{failed=true;}check(failed&&rollback.Commerce.Entitlements==0&&rollback.Commerce.FulfilledTransactions.Count==0,"purchase failed persistence rolls back");
   CommerceRules.RestoreEntitlement(p,CommerceRules.Starter);CommerceRules.ReconcileEntitlements(p,new[]{CommerceRules.Starter,id});check(p.Commerce.Entitlements==5&&p.Styles[4],"Remove Ads coexists with premium rights");CommerceRules.ReconcileEntitlements(p,new[]{CommerceRules.Starter});check(p.Commerce.Entitlements==1&&p.Styles[4],"Remove Ads refund preserves premium");CommerceRules.FulfillPending(p,id,"remove1",x=>{});check(p.Commerce.Entitlements==1,"replayed revoked receipt cannot resurrect ownership");CommerceRules.FulfillPending(p,id,"remove2",x=>{});check(p.Commerce.Entitlements==5,"new verified purchase can reacquire Remove Ads");
   var lockType=assembly.GetType("Kamilunavo.RepairEmpire.Monetization.NativePresentationGate");check(lockType!=null,"shared native provider gate");var native=Activator.CreateInstance(lockType);var first=new object();var second=new object();Func<object,bool> acquire=owner=>(bool)lockType.GetMethod("TryAcquire").Invoke(native,new[]{owner});Func<object,bool> release=owner=>(bool)lockType.GetMethod("Release").Invoke(native,new[]{owner});check(acquire(first)&&!acquire(second),"native providers cannot overlap");check(!release(second)&&!acquire(second),"foreign callback cannot release provider owner");check(release(first)&&!release(first)&&acquire(second),"close/retry owner is idempotent");
   var rewardOpened=policy.GetMethod("DelayAfterRewarded");check(rewardOpened!=null,"voluntary opened video resets shared three minute clock");var shared=fresh();paid(shared,1,"a");paid(shared,2,"b");paid(shared,3,"c");rewardOpened.Invoke(shared,new object[]{300d});check((int)policy.GetProperty("PaidSinceAd").GetValue(shared)==3,"voluntary video preserves paid-order counter");check(!result(shared,3,479.999,ready()),"interstitial cannot open within180seconds of rewarded-open");paid(shared,4,"d");check(result(shared,4,480,ready()),"next new paid result may show180seconds after voluntary video");rewardOpened.Invoke(shared,new object[]{double.NaN});rewardOpened.Invoke(shared,new object[]{1d});paid(shared,5,"e");check(!result(shared,5,479,ready()),"invalid/reversed voluntary clock cannot shorten cooldown");
   Console.WriteLine("REPAIR_INTERSTITIAL_PASS "+n);return n;
  }
#if REPAIR_INTERSTITIAL_EXE
  public static int Main(){try{Run();return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
#endif
 }
}
